"use client";

import { Thinking } from "./thinking";
import { Streaming } from "./streaming";
import { ToolCall, type ToolStep } from "./tool-call";
import { Stalled } from "./stalled";
import { ErrorState } from "./error-state";
import { Done } from "./done";
import { ReasoningTrace } from "./reasoning-trace";
import { Sources, type SourceItem } from "./sources";
import { AgentPlan, type PlanStep } from "./agent-plan";
import { Approval } from "./approval";
import { Queue } from "./queue";
import { FileProcessing, type FileStage } from "./file-processing";
import { cx, type AgentStatus, type AgentStatusSnapshot, type WaitStateProps } from "./types";

export type AgentStateProps = WaitStateProps & {
  status: AgentStatus | AgentStatusSnapshot;
  text?: string;
  toolName?: string;
  steps?: ToolStep[];
  errorMessage?: string;
  onRetry?: () => void;
  onCancel?: () => void;
  reasoning?: string;
  reasoningDone?: boolean;
  reasoningDurationSeconds?: number;
  sources?: SourceItem[];
  planSteps?: PlanStep[];
  approvalTitle?: string;
  approvalPreview?: React.ReactNode;
  onAllow?: () => void;
  onDeny?: () => void;
  approvalExpiresIn?: number;
  queueVariant?: "line" | "rate-limit";
  queuePosition?: number;
  retryIn?: number;
  filename?: string;
  fileSize?: string;
  fileStage?: FileStage;
  fileProgress?: number;
};

function isSnapshot(value: AgentStatus | AgentStatusSnapshot): value is AgentStatusSnapshot {
  return typeof value === "object";
}

export function AgentState({
  status, className, accent = false, text, toolName, steps, errorMessage, onRetry, onCancel,
  reasoning, reasoningDone, reasoningDurationSeconds, sources, planSteps = [], approvalTitle,
  approvalPreview = "Review this action before it runs.", onAllow, onDeny, approvalExpiresIn,
  queueVariant, queuePosition, retryIn, filename = "document.pdf", fileSize = "2.4 MB",
  fileStage, fileProgress,
}: AgentStateProps) {
  const snapshot = isSnapshot(status) ? status : undefined;
  const state: AgentStatus = snapshot ? snapshot.state : (status as AgentStatus);
  const cancel = onCancel ?? snapshot?.cancel;

  return (
    <div key={state} className={cx("crate-state-in motion-reduce:opacity-100", className)} aria-live="polite" aria-atomic="true">
      {state === "thinking" ? <Thinking accent={accent} elapsedMs={snapshot?.elapsedMs} label={snapshot?.label === "Thinking…" ? undefined : snapshot?.label} onCancel={cancel} /> : null}
      {state === "reasoning" ? <ReasoningTrace accent={accent} text={reasoning ?? snapshot?.reasoning} done={reasoningDone} durationSeconds={reasoningDurationSeconds} /> : null}
      {state === "sources" ? <Sources accent={accent} sources={sources ?? snapshot?.sources ?? []} /> : null}
      {state === "tool" ? <ToolCall accent={accent} toolName={toolName ?? snapshot?.activeToolName} steps={steps} /> : null}
      {state === "plan" ? <AgentPlan accent={accent} steps={planSteps} /> : null}
      {state === "approval" ? <Approval accent={accent} title={approvalTitle} preview={approvalPreview} onAllow={onAllow} onDeny={onDeny} expiresIn={approvalExpiresIn} /> : null}
      {state === "queue" ? <Queue accent={accent} variant={queueVariant} position={queuePosition} retryIn={retryIn} /> : null}
      {state === "file" ? <FileProcessing accent={accent} filename={filename} size={fileSize} stage={fileStage} progress={fileProgress} /> : null}
      {state === "streaming" ? <Streaming accent={accent} text={text} /> : null}
      {state === "stalled" ? <Stalled accent={accent} /> : null}
      {state === "error" ? <ErrorState message={errorMessage} onRetry={onRetry} /> : null}
      {state === "done" ? <Done accent={accent} /> : null}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-state-enter { from { opacity: 0; transform: translateY(4px) } to { opacity: 1; transform: none } } .crate-state-in { animation: crate-state-enter 260ms ease-out both; } }`}</style>
    </div>
  );
}

import { cx, type WaitStateProps } from "./types";

export type ThinkingProps = WaitStateProps & {
  elapsedMs?: number;
  onCancel?: () => void;
  label?: string;
};

export function Thinking({ className, accent = false, elapsedMs = 0, onCancel, label }: ThinkingProps) {
  const message = label ?? (elapsedMs >= 8000 ? "Still thinking…" : "Thinking…");
  const visibleLabel = elapsedMs >= 2000 || Boolean(label);
  const canCancel = elapsedMs >= 20000 && Boolean(onCancel);

  return (
    <div className={cx("inline-flex min-h-10 items-center gap-3 rounded-sm border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-20px_color-mix(in_srgb,var(--primary)_30%,transparent)]", className)} aria-live="polite" aria-label={message}>
      <span className="flex items-center gap-1.5" aria-hidden="true">
        {[0, 1, 2].map((index) => <span key={index} className={cx("size-1.5 rounded-full motion-safe:animate-bounce motion-reduce:opacity-70", accent ? "bg-primary" : "bg-muted-foreground")} style={{ animationDelay: `${index * 140}ms` }} />)}
      </span>
      {visibleLabel ? <span>{message}</span> : <span className="sr-only">{message}</span>}
      {canCancel ? <button type="button" onClick={onCancel} className="ml-1 rounded-lg border border-border px-2.5 py-1 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary">Cancel</button> : null}
    </div>
  );
}

import { cx, type WaitStateProps } from "./types";

export type StreamingProps = WaitStateProps & { children?: React.ReactNode; text?: string };

export function Streaming({ className, accent = false, children, text }: StreamingProps) {
  return (
    <span className={cx("text-sm leading-7 text-foreground", className)} aria-live="polite" aria-label="Response streaming">
      {children ?? text}
      <span aria-hidden="true" className={cx("ml-1 inline-block h-[1.05em] w-[3px] translate-y-[2px] rounded-full motion-safe:animate-pulse motion-reduce:opacity-80", accent ? "bg-primary shadow-[0_0_12px_color-mix(in_srgb,var(--primary)_60%,transparent)]" : "bg-foreground")} />
    </span>
  );
}

import { Check, Circle, LoaderCircle, Search, FileText, Wrench } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type ToolStep = { id?: string; label: string; toolName?: string; state?: "pending" | "active" | "complete" };
export type ToolCallProps = WaitStateProps & { steps?: ToolStep[]; toolName?: string; label?: string };

function ToolIcon({ name, active }: { name?: string; active: boolean }) {
  const iconClass = "size-3.5";
  if (active) return <LoaderCircle className={cx(iconClass, "motion-safe:animate-spin")} />;
  if (name?.toLowerCase().includes("search")) return <Search className={iconClass} />;
  if (name?.toLowerCase().includes("file") || name?.toLowerCase().includes("read")) return <FileText className={iconClass} />;
  return <Wrench className={iconClass} />;
}

export function ToolCall({ className, accent = false, steps, toolName = "tool", label }: ToolCallProps) {
  const items = steps?.length ? steps : [{ label: label ?? `Running ${toolName}…`, toolName, state: "active" as const }];
  return (
    <div className={cx("w-full max-w-sm rounded-sm border border-border bg-background p-2 text-foreground shadow-[0_14px_34px_-24px_color-mix(in_srgb,var(--primary)_30%,transparent)]", className)} aria-live="polite" aria-label="Agent tool activity">
      <ol className="space-y-1">
        {items.map((step, index) => {
          const state = step.state ?? (index === items.length - 1 ? "active" : "complete");
          return <li key={step.id ?? `${step.label}-${index}`} className={cx("flex items-center gap-2.5 rounded-md px-3 py-2 text-sm", state === "active" ? "bg-muted text-foreground" : "text-muted-foreground")}>
            <span className={cx("grid size-6 shrink-0 place-items-center rounded-lg border border-border bg-background text-muted-foreground", state === "active" && accent && "text-primary")} aria-hidden="true">
              {state === "complete" ? <Check className="size-3.5" /> : state === "pending" ? <Circle className="size-3" /> : <ToolIcon name={step.toolName} active />}
            </span>
            <span>{step.label}</span>
          </li>;
        })}
      </ol>
    </div>
  );
}

import { Clock3 } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type StalledProps = WaitStateProps & { message?: string };

export function Stalled({ className, accent = false, message = "Still working…" }: StalledProps) {
  return (
    <div className={cx("inline-flex items-center gap-2.5 rounded-sm border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_35%,transparent)]", className)} aria-live="polite">
      <span className={cx("grid size-6 place-items-center rounded-lg bg-muted motion-safe:animate-pulse motion-reduce:opacity-80", accent ? "text-primary" : "text-muted-foreground")} aria-hidden="true"><Clock3 className="size-3.5" /></span>
      {message}
    </div>
  );
}

import { AlertCircle, RotateCcw } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type ErrorStateProps = WaitStateProps & {
  message?: string;
  onRetry?: () => void;
};

export function ErrorState({
  className,
  message = "Something went wrong.",
  onRetry,
}: ErrorStateProps) {
  return (
    <div
      className={cx(
        "flex w-full max-w-sm items-center gap-3 rounded-sm border border-border bg-background p-3 text-sm shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_35%,transparent)]",
        className,
      )}
      role="status"
      aria-live="polite"
    >
      <AlertCircle className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
      <span className="min-w-0 flex-1 text-foreground">{message}</span>
      {onRetry ? (
        <button
          type="button"
          onClick={onRetry}
          className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
        >
          <RotateCcw className="size-3" aria-hidden="true" /> Retry
        </button>
      ) : null}
    </div>
  );
}

export { ErrorState as Error };

import { Check } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type DoneProps = WaitStateProps & { label?: string };

export function Done({ className, accent = false, label = "Done" }: DoneProps) {
  return (
    <span className={cx("crate-done inline-flex items-center gap-2 text-sm text-muted-foreground motion-reduce:opacity-70", className)} aria-live="polite">
      <span className={cx("grid size-6 place-items-center rounded-full bg-muted", accent ? "text-primary" : "text-muted-foreground")} aria-hidden="true"><Check className="size-3.5" strokeWidth={2.5} /></span>
      {label}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-done-fade { 0% { opacity: 0 } 18%, 72% { opacity: 1 } 100% { opacity: .25 } } .crate-done { animation: crate-done-fade 2.4s ease both; } }`}</style>
    </span>
  );
}

"use client";

import { useState } from "react";
import { ChevronDown } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type ReasoningTraceProps = WaitStateProps & {
  text?: string;
  done?: boolean;
  durationSeconds?: number;
  defaultOpen?: boolean;
};

export function ReasoningTrace({ className, accent = false, text = "", done = false, durationSeconds = 12, defaultOpen }: ReasoningTraceProps) {
  const [open, setOpen] = useState(defaultOpen ?? !done);
  const label = done ? `Thought for ${durationSeconds}s` : "Show thinking";

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background text-sm text-foreground", className)}>
      <button type="button" className="flex w-full items-center gap-2 rounded-sm px-4 py-3 text-left font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary" aria-expanded={open} onClick={() => setOpen((value) => !value)}>
        <span className={cx("size-2 rounded-full bg-muted-foreground", accent && !done && "bg-primary motion-safe:animate-pulse")} aria-hidden="true" />
        <span className="flex-1">{label}</span>
        <ChevronDown className={cx("size-4 transition-transform motion-reduce:transition-none", open && "rotate-180")} aria-hidden="true" />
      </button>
      {open ? <div className="border-t border-border px-4 py-3 leading-6 text-muted-foreground" aria-live="polite">{text || "Working through the details…"}{!done ? <span className={cx("ml-1 inline-block size-1.5 rounded-full motion-safe:animate-pulse", accent ? "bg-primary" : "bg-muted-foreground")} aria-hidden="true" /> : null}</div> : null}
    </div>
  );
}

import { Globe2 } from "lucide-react";
import { cx, type AgentSource, type WaitStateProps } from "./types";

export type SourceItem = AgentSource;
export type SourcesProps = WaitStateProps & { sources: SourceItem[]; maxVisible?: number };

function sourceDomain(source: SourceItem) {
  if (source.domain) return source.domain;
  if (!source.url) return "source";
  try { return new URL(source.url).hostname.replace(/^www\./, ""); } catch { return "source"; }
}

export function Sources({ className, accent = false, sources, maxVisible = 3 }: SourcesProps) {
  const visible = sources.slice(0, maxVisible);
  const overflow = Math.max(0, sources.length - visible.length);

  return (
    <div className={cx("flex max-w-xl flex-wrap gap-2", className)} aria-live="polite" aria-label="Sources">
      {visible.map((source, index) => {
        const content = <><span className={cx("grid size-6 shrink-0 place-items-center rounded-md bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><Globe2 className="size-3.5" /></span><span className="min-w-0"><span className="block truncate text-[11px] text-muted-foreground">{sourceDomain(source)}</span><span className="block max-w-44 truncate text-xs font-medium text-foreground">{source.title}</span></span></>;
        const classes = "crate-source flex min-w-0 items-center gap-2 rounded-md border border-border bg-background px-2.5 py-2";
        return source.url ? <a key={source.id ?? source.url ?? index} href={source.url} target="_blank" rel="noreferrer" className={classes} style={{ animationDelay: `${index * 90}ms` }}>{content}</a> : <span key={source.id ?? index} className={classes} style={{ animationDelay: `${index * 90}ms` }}>{content}</span>;
      })}
      {overflow ? <span className="inline-flex items-center rounded-md border border-border bg-muted px-3 text-xs text-muted-foreground">+{overflow} more</span> : null}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-source-in { from { opacity: 0; transform: scale(.96) } to { opacity: 1; transform: none } } .crate-source { animation: crate-source-in 220ms ease-out both; } }`}</style>
    </div>
  );
}

import { Check, Circle, LoaderCircle, X } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type PlanStep = { id?: string; label: string; state: "pending" | "active" | "complete" | "failed" };
export type AgentPlanProps = WaitStateProps & { steps: PlanStep[] };

export function AgentPlan({ className, accent = false, steps }: AgentPlanProps) {
  const complete = steps.filter((step) => step.state === "complete").length;
  const activeIndex = steps.findIndex((step) => step.state === "active");
  const progress = Math.max(complete, activeIndex >= 0 ? activeIndex + 1 : complete);

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="mb-3 flex items-center justify-between text-xs"><span className="font-medium">Plan</span><span className="text-muted-foreground">{Math.min(progress, steps.length)} of {steps.length}</span></div>
      <ol className="space-y-2">
        {steps.map((step, index) => <li key={step.id ?? `${step.label}-${index}`} className={cx("flex items-center gap-2.5 text-sm", step.state === "pending" && "text-muted-foreground")}>
          <span className={cx("grid size-6 shrink-0 place-items-center rounded-full border border-border", step.state === "active" && accent && "border-primary text-primary", step.state === "failed" && "text-destructive")} aria-hidden="true">
            {step.state === "complete" ? <Check className="size-3.5" /> : step.state === "failed" ? <X className="size-3.5" /> : step.state === "active" ? <LoaderCircle className="size-3.5 motion-safe:animate-spin" /> : <Circle className="size-3" />}
          </span>
          <span className={cx(step.state === "complete" && "text-muted-foreground line-through")}>{step.label}</span>
        </li>)}
      </ol>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { ShieldCheck } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type ApprovalProps = WaitStateProps & {
  title?: string;
  preview: React.ReactNode;
  onAllow?: () => void;
  onDeny?: () => void;
  expiresIn?: number;
};

export function Approval({ className, accent = false, title = "The agent wants to send this email", preview, onAllow, onDeny, expiresIn }: ApprovalProps) {
  const [remaining, setRemaining] = useState(expiresIn);

  useEffect(() => {
    setRemaining(expiresIn);
    if (expiresIn === undefined) return;
    const timer = window.setInterval(() => setRemaining((value) => value === undefined ? value : Math.max(0, value - 1)), 1000);
    return () => window.clearInterval(timer);
  }, [expiresIn]);

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} role="group" aria-label="Approval required">
      <div className="flex items-start gap-3">
        <span className={cx("grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><ShieldCheck className="size-4" /></span>
        <div className="min-w-0 flex-1"><p className="m-0 text-sm font-medium">{title}</p>{remaining !== undefined ? <p className="mt-1 text-xs text-muted-foreground" aria-live="polite">Expires in {remaining}s</p> : null}</div>
      </div>
      <div className="my-3 rounded-md border border-border bg-muted p-3 text-sm text-muted-foreground">{preview}</div>
      <div className="flex justify-end gap-2">
        <button type="button" onClick={onDeny} className="rounded-lg border border-border px-3 py-1.5 text-sm text-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary">Deny</button>
        <button type="button" onClick={onAllow} className={cx("rounded-lg border border-border px-3 py-1.5 text-sm font-medium text-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary", accent && "border-primary bg-primary text-primary-foreground hover:opacity-90")}>Allow</button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Clock3, Users } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type QueueProps = WaitStateProps & { variant?: "line" | "rate-limit"; position?: number; retryIn?: number };

export function Queue({ className, accent = false, variant = "line", position = 3, retryIn = 20 }: QueueProps) {
  const [value, setValue] = useState(variant === "line" ? position : retryIn);
  useEffect(() => {
    setValue(variant === "line" ? position : retryIn);
    const timer = window.setInterval(() => setValue((current) => Math.max(0, current - 1)), variant === "line" ? 3500 : 1000);
    return () => window.clearInterval(timer);
  }, [position, retryIn, variant]);
  const message = variant === "line" ? `You’re #${Math.max(1, value)} in line` : `Slow down. Try again in ${value}s`;
  const Icon = variant === "line" ? Users : Clock3;
  return <div className={cx("inline-flex items-center gap-3 rounded-sm border border-border bg-background px-4 py-3 text-sm text-foreground", className)} aria-live="polite"><span className={cx("grid size-7 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><Icon className="size-4" /></span><span>{message}</span></div>;
}

import { Check, FileText, LoaderCircle } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type FileStage = "uploading" | "reading" | "chunking" | "ready";
export type FileProcessingProps = WaitStateProps & { filename: string; size: string; stage?: FileStage; progress?: number };

const stages: Array<{ key: FileStage; label: string }> = [
  { key: "uploading", label: "Upload" },
  { key: "reading", label: "Reading" },
  { key: "chunking", label: "Chunking" },
  { key: "ready", label: "Ready" },
];

export function FileProcessing({ className, accent = false, filename, size, stage = "uploading", progress = 0 }: FileProcessingProps) {
  const activeIndex = stages.findIndex((item) => item.key === stage);
  const percent = stage === "ready" ? 100 : Math.max(0, Math.min(100, progress));
  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="flex items-center gap-3"><span className={cx("grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><FileText className="size-4" /></span><div className="min-w-0 flex-1"><p className="m-0 truncate text-sm font-medium">{filename}</p><p className="m-0 text-xs text-muted-foreground">{size}</p></div><span className="text-xs text-muted-foreground">{percent}%</span></div>
      <div className="my-3 h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden="true"><span className={cx("block h-full rounded-full bg-muted-foreground transition-[width] motion-reduce:transition-none", accent && "bg-primary")} style={{ width: `${percent}%` }} /></div>
      <ol className="grid grid-cols-4 gap-1 text-center text-[10px] text-muted-foreground">
        {stages.map((item, index) => <li key={item.key} className={cx("flex min-w-0 flex-col items-center gap-1", index === activeIndex && "text-foreground")}><span className={cx("grid size-5 place-items-center rounded-full border border-border", index === activeIndex && accent && "border-primary text-primary")} aria-hidden="true">{index < activeIndex || stage === "ready" ? <Check className="size-3" /> : index === activeIndex ? <LoaderCircle className="size-3 motion-safe:animate-spin" /> : null}</span><span className="truncate">{item.label}</span></li>)}
      </ol>
    </div>
  );
}

export type AgentStatus =
  | "thinking"
  | "reasoning"
  | "sources"
  | "tool"
  | "plan"
  | "approval"
  | "queue"
  | "file"
  | "streaming"
  | "stalled"
  | "error"
  | "done";

export type AgentSource = {
  id?: string;
  url?: string;
  domain?: string;
  title: string;
};

export type AgentStatusSnapshot = {
  state: AgentStatus;
  activeToolName?: string;
  reasoning?: string;
  sources: AgentSource[];
  elapsedMs: number;
  showCancel: boolean;
  label: string;
  cancel?: () => void;
};

export type WaitStateProps = {
  className?: string;
  accent?: boolean;
};

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

export { AgentState, type AgentStateProps } from "./agent-state";
export { Thinking, type ThinkingProps } from "./thinking";
export { Streaming, type StreamingProps } from "./streaming";
export { ToolCall, type ToolCallProps, type ToolStep } from "./tool-call";
export { Stalled, type StalledProps } from "./stalled";
export { Error, ErrorState, type ErrorStateProps } from "./error-state";
export { Done, type DoneProps } from "./done";
export { ReasoningTrace, type ReasoningTraceProps } from "./reasoning-trace";
export { Sources, type SourcesProps, type SourceItem } from "./sources";
export { AgentPlan, type AgentPlanProps, type PlanStep } from "./agent-plan";
export { Approval, type ApprovalProps } from "./approval";
export { Queue, type QueueProps } from "./queue";
export { FileProcessing, type FileProcessingProps, type FileStage } from "./file-processing";
export type { AgentStatus, AgentStatusSnapshot, AgentSource, WaitStateProps } from "./types";

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { AgentSource, AgentStatus, AgentStatusSnapshot } from "@/components/agent-wait-states/types";

type UnknownPart = {
  type?: string;
  text?: string;
  state?: string;
  toolName?: string;
  url?: string;
  title?: string;
  sourceId?: string;
  filename?: string;
  toolInvocation?: { toolName?: string; state?: string };
};

type ChatLike = {
  status: "submitted" | "streaming" | "ready" | "error" | string;
  messages: Array<{ role?: string; parts?: UnknownPart[]; content?: string }>;
  error?: unknown;
  stop?: () => void;
};

export type UseAgentStatusOptions = { manualStatus?: AgentStatus; onCancel?: () => void; stallAfterMs?: number };

const FINISHED_TOOL_STATES = new Set(["output-available", "output-error", "result", "error"]);

function readTool(part: UnknownPart) {
  const type = part.type ?? "";
  const invocation = part.toolInvocation;
  const name = part.toolName ?? invocation?.toolName ?? (type.startsWith("tool-") ? type.slice(5) : undefined);
  const state = part.state ?? invocation?.state;
  const isTool = type === "dynamic-tool" || type === "tool-invocation" || type.startsWith("tool-");
  return isTool && name && !FINISHED_TOOL_STATES.has(state ?? "") ? name : undefined;
}

function inspectMessages(messages: ChatLike["messages"]) {
  let activeToolName: string | undefined;
  let content = "";
  let reasoning = "";
  let latestPart: "text" | "reasoning" | "source" | "other" = "other";
  const sources: AgentSource[] = [];

  for (const message of messages) {
    if (message.content) content += message.content;
    for (const part of message.parts ?? []) {
      const type = part.type ?? "";
      if (type === "text" && part.text) { content += part.text; latestPart = "text"; }
      if (type === "reasoning" || type === "reasoning-text") {
        reasoning += part.text ?? "";
        latestPart = "reasoning";
      }
      if (type === "source-url" || type === "source-document" || type === "source") {
        sources.push({
          id: part.sourceId,
          url: part.url,
          title: part.title ?? part.filename ?? part.url ?? "Source",
        });
        latestPart = "source";
      }
      const toolName = readTool(part);
      if (toolName) { activeToolName = toolName; latestPart = "other"; }
    }
  }

  return {
    activeToolName,
    reasoning,
    sources,
    latestPart,
    contentSignature: `${content.length}:${content.slice(-80)}:${reasoning.length}:${sources.length}`,
  };
}

export function useAgentStatus(chat: ChatLike, options: UseAgentStatusOptions = {}): AgentStatusSnapshot {
  const inspected = useMemo(() => inspectMessages(chat.messages), [chat.messages]);
  const [now, setNow] = useState(() => Date.now());
  const busySince = useRef<number | null>(null);
  const lastContentAt = useRef(Date.now());
  const previousSignature = useRef(inspected.contentSignature);
  const busy = chat.status === "submitted" || chat.status === "streaming";

  useEffect(() => {
    if (busy && busySince.current === null) busySince.current = Date.now();
    if (!busy) busySince.current = null;
  }, [busy]);

  useEffect(() => {
    if (inspected.contentSignature !== previousSignature.current) {
      previousSignature.current = inspected.contentSignature;
      lastContentAt.current = Date.now();
      setNow(Date.now());
    }
  }, [inspected.contentSignature]);

  useEffect(() => {
    if (!busy) return;
    const timer = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(timer);
  }, [busy]);

  const elapsedMs = busySince.current ? Math.max(0, now - busySince.current) : 0;
  const stalled = chat.status === "streaming" && now - lastContentAt.current >= (options.stallAfterMs ?? 5000);

  let state: AgentStatus;
  if (options.manualStatus) state = options.manualStatus;
  else if (chat.status === "error" || chat.error) state = "error";
  else if (stalled) state = "stalled";
  else if (inspected.activeToolName && busy) state = "tool";
  else if (chat.status === "streaming" && inspected.latestPart === "reasoning") state = "reasoning";
  else if (chat.status === "streaming" && inspected.latestPart === "source") state = "sources";
  else if (chat.status === "streaming") state = "streaming";
  else if (chat.status === "submitted") state = "thinking";
  else state = "done";

  const label = elapsedMs >= 8000 ? "Still thinking…" : "Thinking…";
  const cancel = options.onCancel ?? chat.stop;

  return {
    state,
    activeToolName: inspected.activeToolName,
    reasoning: inspected.reasoning || undefined,
    sources: inspected.sources,
    elapsedMs,
    showCancel: elapsedMs >= 20000 && Boolean(cancel),
    label,
    cancel,
  };
}
